import {lockNotice} from './plan-workflow.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未记录';
const names={fire:'火',water:'水',metal:'金',earth:'土',wood:'木'};
export function reconciliationFields(card){
 if(!card.trade?.requiresReconciliation)return '';
 return `<details class="form-section"><summary>持仓待对账：核对交易软件的当前实际持仓</summary><form id="reconcilePositionForm"><input type="hidden" name="requestId" value="${crypto.randomUUID()}"><div class="form-grid"><label class="field">核对时间<input type="datetime-local" name="time" value="${new Date(Date.now()+8*3600000).toISOString().slice(0,16)}" required></label><label class="field">实际方向<select name="direction"><option value="long" ${card.trade.direction==='long'?'selected':''}>多头</option><option value="short" ${card.trade.direction==='short'?'selected':''}>空头</option></select></label><label class="field">当前剩余手数（已退出填0）<input type="number" name="quantity" min="0" step="1" required></label><label class="field">当前实际持仓均价<input type="number" name="price" step="any"></label><label class="field">当前止损保护价<input type="number" name="stop" step="any"></label><label class="field wide">回报依据与核对说明<input name="reason" required></label></div><p class="muted">原成交保留。此处只核对当前持仓，不重复入账盈亏；账户金额按实际结算核对。</p><button class="secondary">保存持仓对账</button></form></details>`;
}
export function governancePanel(g,rules){
 const r=g.active;
 return `<section class="form-section" id="governancePanel"><h3>团队运行 · ${r?'本轮框架已锁定':'尚未启动新一轮'}</h3><p>${r?`${esc(time(r.startedAt))} · ${esc(r.id.slice(0,8))} · 规则 ${esc(r.snapshot.combinedHash.slice(0,12))}`:'首次冻结计划时锁定框架，也可在此提前启动。'}</p>${lockNotice(rules,false)}<details><summary>五行职责与边界</summary>${Object.values(r?.snapshot?.responsibilities||g.responsibilities).map(s=>`<p>${esc(s)}</p>`).join('')}<p>运行中只记录修订建议，不启用新规则。整轮结束、结果落地后再修订。</p><small>${esc(g.reviewMode)}</small></details><div class="actions">${r?'<button type="button" class="secondary" id="finishSystemRun">结束本轮并记录结果</button>':'<button type="button" class="secondary" id="startSystemRun">启动并锁定框架</button>'}</div><details><summary>运行历史（${g.history.length}）</summary>${g.history.map(x=>`<p>${esc(time(x.startedAt))} · ${esc(x.status)} · ${esc(x.result||'结果尚未落地')}</p>`).join('')}</details></section>`;
}
export function supervisionPanel(card){
 return `<section class="form-section"><h3>全过程记录</h3><div class="table-wrap"><table><thead><tr><th>环节</th><th>当前证据</th></tr></thead><tbody><tr><td>火</td><td>${esc(card.fire?.result||'未记录')} · ${esc(card.fire?.dataDate||'日期未知')}</td></tr><tr><td>水</td><td>${esc(card.water?.conclusion||'研究结论待补')}</td></tr><tr><td>金</td><td>${esc(card.plan?.status||'未冻结')} · ${esc(card.plan?.risk?.reviewScope||'复核范围待核验')}</td></tr><tr><td>土</td><td>${card.executions.length} 条记录 · ${esc(card.trade?.outcome)}</td></tr></tbody></table></div><details><summary>证据与历史变更（${card.timeline?.length||0}）</summary>${(card.timeline||[]).map(x=>`<article class="review-version"><b>${esc(time(x.createdAt))} · ${esc(x.action)}</b><details><summary>原始记录</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(x.payload,null,2))}</pre></details></article>`).join('')}</details><h3>待办与异常</h3>${(card.supervision||[]).map(x=>`<article class="review-version"><b>${esc(names[x.owner])} · ${esc(x.status)}</b><p>${esc(x.description)}</p><p>下一步：${esc(x.next_action)}</p>${x.resolution?`<p>处理结果：${esc(x.resolution)}</p>`:`<button type="button" class="secondary" data-resolve-issue="${esc(x.id)}">登记处理结果</button>`}</article>`).join('')||'<p class="muted">暂无已登记异常；不代表完成独立核验。</p>'}<form id="issueForm"><div class="form-grid"><label class="field">责任环节<select name="owner">${Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="field">问题或下轮修订建议<input name="description" required></label><label class="field wide">下一步<input name="nextAction" required></label></div><button class="secondary">登记事项</button></form>${card.plan?.approvedAt?'<button type="button" class="secondary" id="releaseReservation">核对并撤销未成交预留</button>':''}</section>`;
}
export function bindGovernance({api,toast,reload,card}){
 const submit=async(path,body)=>{try{await api(path,{method:'POST',body:JSON.stringify(body)});await reload()}catch(e){toast(e.message,true)}};
 const start=document.querySelector('#startSystemRun');if(start)start.onclick=()=>submit('/api/workbench/governance/start',{});
 const finish=document.querySelector('#finishSystemRun');if(finish)finish.onclick=()=>{const result=prompt('请逐账户核对交易软件：本轮无实际持仓、无未确认委托、未成交预留已取消。填写核对结果；结束会保留旧快照与全部记录，下次计划锁定当前版本，不重置原交易轮次预算。');if(result)submit('/api/workbench/governance/finish',{result})};
 document.querySelectorAll('[data-resolve-issue]').forEach(b=>b.onclick=()=>{const resolution=prompt('记录实际处理结果；保留原问题，不删除事实。');if(resolution)submit('/api/workbench/governance/issues',{id:b.dataset.resolveIssue,resolution})});
 const form=document.querySelector('#issueForm');if(form)form.onsubmit=e=>{e.preventDefault();submit('/api/workbench/governance/issues',{...Object.fromEntries(new FormData(form)),cardId:card.id})};
 const release=document.querySelector('#releaseReservation');if(release)release.onclick=()=>{const reason=prompt('确认交易软件中未成交委托已撤销或从未提交。填写核对依据；只释放未成交预留，不删除持仓。');if(reason)submit('/api/workbench/cards/'+card.id+'/release',{reason})};
 const reconcile=document.querySelector('#reconcilePositionForm');if(reconcile)reconcile.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(reconcile));for(const k of ['quantity','price','stop'])data[k]=data[k]===''?null:Number(data[k]);submit('/api/workbench/cards/'+card.id+'/reconcile-position',data)};
}
